//! Text templates for every generated file. Pure functions, unit-tested.
use crate::config::{lease_seconds, Binding, Config, RootMode};
use crate::util::fill;

/// DHCP is served by Kea (kea-dhcp4-server), TFTP by tftpd-hpa. The whole Kea config is generated: the static
/// MAC -> IP bindings (`pxe-ctl bind`, kept in HOSTS_FILE) become its "reservations" and `pxe-ctl bind / unbind`
/// regenerate it. The first line is the marker that tells us a Kea config is ours and may be rewritten.
pub const KEA_CONF_PATH: &str = "/etc/kea/kea-dhcp4.conf";
pub const GENERATED_MARK: &str = "// generated by pxe-installer";
/// Kea's lease file (memfile backend, CSV); `pxe-ctl status` reads it.
pub const KEA_LEASES_PATH: &str = "/var/lib/kea/kea-leases4.csv";
pub const DHCP_SERVICE: &str = "kea-dhcp4-server";
pub const TFTP_SERVICE: &str = "tftpd-hpa";
/// Debian/Ubuntu read tftpd-hpa's settings from here.
pub const TFTPD_DEFAULT_PATH: &str = "/etc/default/tftpd-hpa";

/// Multicast mode (DRBL + Clonezilla SE): the folders whose scripts Clonezilla SE runs on every client before /
/// after the restore (`drbl-ocs ... -o0 -o1`), and our two scripts in them. They do for multicast what
/// `ocs_prerun1` / `ocs_postrun1-2` in grub.cfg do for unicast: the start call (deploy time), and the per-MAC
/// post.sh (hostname, machine-id, SSH keys, pxe-done = done marker + deploy time).
pub const DRBL_PRERUN_DIR: &str = "/usr/share/drbl/prerun/ocs";
pub const DRBL_POSTRUN_DIR: &str = "/usr/share/drbl/postrun/ocs";
pub const PRERUN_HOOK_NAME: &str = "pxe-installer-start.sh";
pub const POSTRUN_HOOK_NAME: &str = "pxe-installer-post.sh";

// UEFI PXE: the client architecture (option 93) is 7 = x64 UEFI or 9 = x64 UEFI (EBC); only those get the boot
// file. Legacy BIOS clients are intentionally not served a boot file. Static bindings (and the pool, unless
// ONLY_KNOWN_HOSTS) are filled in below; DNS is not served here, the clients are pointed at UPSTREAM_DNS.
const KEA_DHCP4: &str = r#"// generated by pxe-installer - do not edit by hand (pxe-ctl bind / unbind rewrite it)
{
  "Dhcp4": {
    "interfaces-config": { "interfaces": [ @IFACE@ ] },
    "lease-database": { "type": "memfile", "persist": true, "lfc-interval": 3600 },
    "valid-lifetime": @LIFETIME@,
    "client-classes": [
      {
        "name": "pxe-uefi-x64",
        "test": "option[93].hex == 0x0007 or option[93].hex == 0x0009",
        "boot-file-name": "bootx64.efi"
      }
    ],
    "subnet4": [
      {
        "id": 1,
        "subnet": @SUBNET@,
        "next-server": @SERVER_IP@,
        "pools": [ @POOLS@ ],
        "option-data": [
          { "name": "routers", "data": @SERVER_IP@ },
          { "name": "domain-name-servers", "data": @DNS@ }
        ],
        "reservations": [
@RESERVATIONS@
        ]
      }
    ]
  }
}
"#;

// Clonezilla Live over PXE. The kernel and initrd come from the TFTP root (/clonezilla/); the image
// repository is mounted over NFS on /home/partimag. The live system itself is delivered in one of two
// ways (@ROOT_ARGS@, see ROOT_MODE): `fetch=` downloads filesystem.squashfs over HTTP into the target's RAM
// (root = tmpfs overlay), or `netboot=nfs nfsroot=` mounts the extracted Clonezilla Live folder from the
// server over NFS (diskless root, no RAM copy). After the restore Clonezilla runs post.sh (generated per MAC by `cgi-seed`): it gives
// the clone its own hostname / machine-id / SSH host keys and calls pxe-done, which creates the marker
// that makes the guard at the top of this file skip the host on its next PXE boot. The restore entry also
// calls pxe-seed/<mac>/start (ocs_prerun1) when Clonezilla comes up: that is the start of the deploy time
// the server records per MAC (start -> pxe-done, see `pxe-ctl times`).
//
// There is no `ip=` argument on purpose: with fetch= the live-boot initramfs configures the network with
// DHCP by itself. `ip=dhcp` is read as a device name ("ip: can't find device 'dhcp'") and an empty `ip=`
// becomes `ip=frommedia` ("ip: can't find device 'frommedia'"); either way eth0 gets no address.
//
// Notes on the syntax: the `\"` pairs put literal double quotes on the kernel command line, which
// Clonezilla needs for values that contain spaces. `&&` and `;` are GRUB operators, so every command is
// a separate ocs_postrunN instead of one chained line.
/// First line of the generated grub.cfg. `install` unpacks the Ubuntu netboot tarball over the TFTP root
/// (it ships its own grub/grub.cfg) and uses this marker to put our menu back if one was already written.
pub const GRUB_MARK: &str = "# generated by pxe-installer (PXE menu)";

const GRUB: &str = r#"# generated by pxe-installer (PXE menu) - do not edit by hand
set timeout=5
set default=@DEFAULT@

# Already restored? -> leave grub; UEFI firmware continues with the next boot entry (local disk).
if [ -f /done/${net_default_mac} ]; then
    echo "Host ${net_default_mac} is already installed - booting from local disk."
    sleep 2
    exit
fi

menuentry "Clonezilla Live (interactive - nothing is changed automatically)" {
    echo "Loading Clonezilla Live..."
    linux /clonezilla/vmlinuz boot=live union=overlay username=user config noswap nomodeset noprompt net.ifnames=0 keyboard-layouts= locales= @ROOT_ARGS@ ocs_prerun=\"mount -t nfs -o ro,vers=3,tcp,rsize=1048576 @SERVER_IP@:@IMAGE_DIR@ /home/partimag\" ocs_live_run=\"ocs-live-general\" ocs_live_extra_param=\"\" ocs_live_batch=\"no\" ---
    initrd /clonezilla/initrd.img
}
menuentry "Restore @IMAGE_NAME@ to /dev/@TARGET_DISK@ (ERASES THE DISK)" {
    echo "Loading Clonezilla Live..."
    linux /clonezilla/vmlinuz boot=live union=overlay username=user config noswap nomodeset noprompt net.ifnames=0 keyboard-layouts= locales= @ROOT_ARGS@ ocs_prerun=\"mount -t nfs -o ro,vers=3,tcp,rsize=1048576 @SERVER_IP@:@IMAGE_DIR@ /home/partimag\" ocs_prerun1=\"wget -q -T 5 -t 2 -O /dev/null http://@SERVER_IP@/cgi-bin/pxe-seed/${net_default_mac}/start\" ocs_live_run=\"ocs-sr -g auto -e1 auto -e2 -batch -r -j2 -scr -p true restoredisk @IMAGE_NAME@ @TARGET_DISK@\" ocs_live_extra_param=\"\" ocs_live_keymap=\"NONE\" ocs_lang=\"en_US.UTF-8\" ocs_live_batch=\"yes\" ocs_postrun1=\"wget -q -O /tmp/post.sh http://@SERVER_IP@/cgi-bin/pxe-seed/${net_default_mac}/post.sh\" ocs_postrun2=\"sh /tmp/post.sh\" ocs_postrun3=\"reboot\" ---
    initrd /clonezilla/initrd.img
}
menuentry "Boot from local disk" {
    exit
}
"#;

// Run by Clonezilla Live after the restore (see GRUB above). Served by `pxe-installer cgi-seed` at
// /cgi-bin/pxe-seed/<mac>/post.sh with the hostname bound to that MAC. A clone is an exact copy of the
// source, so it must not keep the source's identity. Any failure aborts before the pxe-done call, so the
// host gets no marker and is restored again on its next PXE boot.
const POST_SCRIPT: &str = r#"#!/bin/sh
# post-restore for @MAC@ (generated by pxe-installer)
set -eu
T=/mnt/target
mkdir -p $T

# find the restored root filesystem on the target disk
root=""
for p in /dev/@DISK@?*; do
    [ -b "$p" ] || continue
    if mount "$p" $T 2>/dev/null; then
        if [ -d $T/etc ] && [ -d $T/usr ]; then
            root=$p
            break
        fi
        umount $T
    fi
done
[ -n "$root" ] || { echo "post.sh: no root filesystem found on /dev/@DISK@" >&2; exit 1; }
echo "post.sh: root filesystem is $root"

# identity of the clone
echo "@HOSTNAME@" > $T/etc/hostname
if [ -f $T/etc/hosts ]; then
    sed -i "s/^127\.0\.1\.1.*/127.0.1.1 @HOSTNAME@/" $T/etc/hosts
fi
: > $T/etc/machine-id
rm -f $T/var/lib/dbus/machine-id
# network config of the PXE server (when the image was taken from it) must not be cloned
rm -f $T/etc/netplan/60-pxe.yaml
# static IP bound to this MAC (pxe-ctl bind <mac> <ip>): the image's netplan files go to a backup folder and the
# bound address is written instead. A MAC without a binding keeps the network config of the image.
ip_cidr="@IP_CIDR@"
if [ -n "$ip_cidr" ]; then
    mkdir -p $T/etc/netplan/backup
    for f in $T/etc/netplan/*; do
        if [ -f "$f" ]; then mv "$f" $T/etc/netplan/backup/; fi
    done
    cat > $T/etc/netplan/01-pxe-server-mac-binding.yaml <<EOF
network:
  version: 2
  ethernets:
    eth0:
      addresses:
      - $ip_cidr
      dhcp4: false
EOF
    chmod 600 $T/etc/netplan/01-pxe-server-mac-binding.yaml
    echo "post.sh: static IP $ip_cidr on eth0 (netplan backup in /etc/netplan/backup)"
fi
rm -f $T/etc/ssh/ssh_host_*
for d in dev proc sys; do mount --bind /$d $T/$d; done
chroot $T ssh-keygen -A || echo "post.sh: ssh-keygen -A failed" >&2
for d in dev proc sys; do umount $T/$d; done
umount $T

# tell the PXE server this MAC is done (creates the marker that stops the next PXE restore)
wget -q -O - "http://@SERVER_IP@/cgi-bin/pxe-done?mac=@MAC@"
"#;

const NETPLAN: &str = "\
network:
  version: 2
  ethernets:
    @IFACE@:
      dhcp4: false
      addresses: [@SERVER_IP@/@PREFIX@]
";

const APACHE_CONF: &str = "\
<Location \"/cgi-bin/pxe-done\">
    Require ip @NETWORK@/@PREFIX@
</Location>
<Location \"/cgi-bin/pxe-seed\">
    Require ip @NETWORK@/@PREFIX@
</Location>
";

pub const SELF_PATH: &str = "/usr/local/sbin/pxe-installer";
pub const CTL_WRAPPER_PATH: &str = "/usr/local/sbin/pxe-ctl";
pub const CGI_PATH: &str = "/usr/lib/cgi-bin/pxe-done";
pub const CGI_SEED_PATH: &str = "/usr/lib/cgi-bin/pxe-seed";

/// A JSON string literal. The values are validated elsewhere; this only keeps a stray quote or backslash
/// (for example in an edited hosts file) from breaking the whole DHCP config.
fn js(s: &str) -> String {
    let mut out = String::from("\"");
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 => out.push(' '),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// The Kea DHCPv4 config: address pool (none with ONLY_KNOWN_HOSTS: then only hosts with a reservation get
/// an address), UEFI boot file, TFTP server (next-server) and one reservation per static binding.
pub fn kea_conf(c: &Config, reservations: &[Binding]) -> String {
    let subnet = format!("{}/{}", c.network().map(|n| n.to_string()).unwrap_or_default(), c.prefix);
    let pools = if c.only_known_hosts {
        String::new()
    } else {
        format!("{{ \"pool\": {} }}", js(&format!("{} - {}", c.dhcp_start, c.dhcp_end)))
    };
    let hosts: Vec<String> = reservations
        .iter()
        .map(|b| {
            let name = if b.hostname.is_empty() { String::new() } else { format!(", \"hostname\": {}", js(&b.hostname)) };
            format!("          {{ \"hw-address\": {}, \"ip-address\": {}{name} }}", js(&b.mac), js(&b.ip))
        })
        .collect();
    fill(
        KEA_DHCP4,
        &[
            ("IFACE", js(&c.iface).as_str()),
            ("LIFETIME", lease_seconds(&c.lease).to_string().as_str()),
            ("SUBNET", js(&subnet).as_str()),
            ("SERVER_IP", js(&c.server_ip).as_str()),
            ("POOLS", pools.as_str()),
            ("DNS", js(&c.upstream_dns).as_str()),
            ("RESERVATIONS", hosts.join(",\n").as_str()),
        ],
    )
}

/// /etc/default/tftpd-hpa: read-only TFTP server chrooted (--secure) into the TFTP root, on UDP 69.
pub fn tftpd_defaults(c: &Config) -> String {
    format!(
        "# generated by pxe-installer - do not edit by hand\n\
         TFTP_USERNAME=\"tftp\"\n\
         TFTP_DIRECTORY=\"{}\"\n\
         TFTP_ADDRESS=\":69\"\n\
         TFTP_OPTIONS=\"--secure\"\n",
        c.tftp_root
    )
}

// The two scripts Clonezilla SE runs on every client (see DRBL_PRERUN_DIR). @MAC_SNIPPET@ puts the MAC of the NIC
// that reaches the PXE server into $mac (in unicast mode GRUB passes the same value as ${net_default_mac});
// when it cannot be found the script says so and exits with @FAIL@.
const HOOK_MAC: &str = r#"dev=$(ip -o route get @SERVER_IP@ 2>/dev/null | sed -n 's/.* dev \([^ ]*\).*/\1/p' | head -n 1)
mac=$(cat "/sys/class/net/$dev/address" 2>/dev/null | tr 'A-F' 'a-f')
case "$mac" in
  ??:??:??:??:??:??) ;;
  *) echo "pxe-installer hook: cannot find the MAC of the NIC that reaches @SERVER_IP@" >&2; exit @FAIL@ ;;
esac
"#;

const PRERUN_HOOK: &str = r#"#!/bin/sh
# pxe-installer (generated): Clonezilla SE runs this on the client before the multicast restore
@MAC_SNIPPET@wget -q -T 5 -t 2 -O /dev/null "http://@SERVER_IP@/cgi-bin/pxe-seed/$mac/start" || true
exit 0
"#;

const POSTRUN_HOOK: &str = r#"#!/bin/sh
# pxe-installer (generated): Clonezilla SE runs this on the client after the multicast restore
[ -e /tmp/pxe-installer-post.done ] && exit 0
@MAC_SNIPPET@wget -q -T 10 -t 3 -O /tmp/post.sh "http://@SERVER_IP@/cgi-bin/pxe-seed/$mac/post.sh" \
  || { echo "pxe-installer hook: cannot fetch post.sh from @SERVER_IP@" >&2; exit 1; }
sh /tmp/post.sh || { echo "pxe-installer hook: post.sh failed" >&2; exit 1; }
touch /tmp/pxe-installer-post.done
"#;

fn client_hook(template: &str, c: &Config, fail: &str) -> String {
    fill(template, &[("MAC_SNIPPET", HOOK_MAC), ("SERVER_IP", c.server_ip.as_str()), ("FAIL", fail)])
}

/// Runs on the client BEFORE the multicast restore: tells the server the deploy starts now (deploy time).
/// Never fails: a missing start only leaves the elapsed time empty.
pub fn prerun_hook(c: &Config) -> String {
    client_hook(PRERUN_HOOK, c, "0")
}

/// Runs on the client AFTER the multicast restore: fetches the post-restore script the server generates for
/// this MAC (hostname bound to the MAC, new machine-id, new SSH host keys, the PXE server's netplan file
/// removed; it ends with pxe-done = done marker + deploy time) and runs it, exactly as the unicast boot menu does.
/// A failure exits non-zero and leaves no done marker.
pub fn postrun_hook(c: &Config) -> String {
    client_hook(POSTRUN_HOOK, c, "1")
}

pub fn grub_cfg(c: &Config) -> String {
    // entries: 0 = interactive Clonezilla, 1 = restore the image, 2 = local disk
    let default = if c.auto_install { "1" } else { "0" };
    let root_args = match c.root_mode {
        RootMode::Tmpfs => format!("fetch=http://{}/clonezilla/filesystem.squashfs", c.server_ip),
        RootMode::Nfs => format!("netboot=nfs nfsroot={}:{}", c.server_ip, c.live_root),
    };
    fill(
        GRUB,
        &[
            ("DEFAULT", default),
            ("ROOT_ARGS", root_args.as_str()),
            ("SERVER_IP", c.server_ip.as_str()),
            ("IMAGE_DIR", c.image_dir.as_str()),
            ("IMAGE_NAME", c.image_name.as_str()),
            ("TARGET_DISK", c.target_disk.as_str()),
        ],
    )
}

/// Post-restore script for one host. `hostname`, `mac` and `ip` must already be validated (they end up in a
/// root shell script on the target). `ip` is the address bound to the MAC (`pxe-ctl bind`), or empty: then the
/// script leaves the network config of the image alone. The address gets the subnet's prefix length (netplan
/// needs `a.b.c.d/nn`).
pub fn post_script(c: &Config, hostname: &str, mac: &str, ip: &str) -> String {
    let ip_cidr = if ip.is_empty() { String::new() } else { format!("{ip}/{}", c.prefix) };
    fill(
        POST_SCRIPT,
        &[
            ("HOSTNAME", hostname),
            ("SERVER_IP", c.server_ip.as_str()),
            ("MAC", mac),
            ("DISK", c.target_disk.as_str()),
            ("IP_CIDR", ip_cidr.as_str()),
        ],
    )
}

pub fn netplan(c: &Config) -> String {
    fill(
        NETPLAN,
        &[("IFACE", c.iface.as_str()), ("SERVER_IP", c.server_ip.as_str()), ("PREFIX", c.prefix.to_string().as_str())],
    )
}

pub fn apache_conf(c: &Config) -> String {
    let net = c.network().map(|n| n.to_string()).unwrap_or_default();
    fill(APACHE_CONF, &[("NETWORK", net.as_str()), ("PREFIX", c.prefix.to_string().as_str())])
}

/// Tiny CGI shim: Apache runs it as www-data, it re-enters this binary.
pub fn cgi_wrapper() -> String {
    format!("#!/bin/sh\nexec {SELF_PATH} cgi-done\n")
}

/// CGI shim that serves the per-MAC post-restore script, see ctl::cgi_seed.
pub fn cgi_seed_wrapper() -> String {
    format!("#!/bin/sh\nexec {SELF_PATH} cgi-seed\n")
}

pub fn ctl_wrapper() -> String {
    format!("#!/bin/sh\nexec {SELF_PATH} ctl \"$@\"\n")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg() -> Config {
        Config::default()
    }

    /// Without a JSON crate: braces and brackets balance (outside strings) and no placeholder is left.
    fn assert_json_shape(s: &str) {
        let body: String = s.lines().filter(|l| !l.trim_start().starts_with("//")).collect::<Vec<_>>().join("\n");
        let (mut depth, mut in_str, mut esc) = (0i32, false, false);
        for ch in body.chars() {
            match (in_str, esc, ch) {
                (true, true, _) => esc = false,
                (true, false, '\\') => esc = true,
                (true, false, '"') => in_str = false,
                (true, false, _) => {}
                (false, _, '"') => in_str = true,
                (false, _, '{') | (false, _, '[') => depth += 1,
                (false, _, '}') | (false, _, ']') => depth -= 1,
                _ => {}
            }
            assert!(depth >= 0, "closing bracket without opening one:\n{s}");
        }
        assert!(!in_str && depth == 0, "unbalanced:\n{s}");
        assert!(!body.contains('@'), "unreplaced placeholder:\n{s}");
    }

    #[test]
    fn kea_has_pool_uefi_boot_and_tftp_server() {
        let s = kea_conf(&cfg(), &[]);
        assert!(s.starts_with(GENERATED_MARK));
        assert_json_shape(&s);
        assert!(s.contains(r#""interfaces": [ "eth0" ]"#));
        assert!(s.contains(r#""subnet": "192.168.5.0/24""#));
        assert!(s.contains(r#""pool": "192.168.5.100 - 192.168.5.200""#));
        assert!(s.contains(r#""valid-lifetime": 86400"#)); // LEASE=24h
        // UEFI x64 clients (option 93 = 7 or 9) get bootx64.efi from the server's TFTP
        assert!(s.contains("option[93].hex == 0x0007") && s.contains("option[93].hex == 0x0009"));
        assert!(s.contains(r#""boot-file-name": "bootx64.efi""#));
        assert!(s.contains(r#""next-server": "192.168.5.1""#));
        assert!(s.contains(r#""name": "domain-name-servers", "data": "8.8.8.8""#));
        assert!(!s.contains("hw-address"));
    }

    #[test]
    fn kea_reservations_and_only_known() {
        let b = |mac: &str, ip: &str, name: &str| Binding { mac: mac.into(), ip: ip.into(), hostname: name.into() };
        let res = [b("aa:bb:cc:dd:ee:01", "192.168.5.11", "node01"), b("aa:bb:cc:dd:ee:02", "192.168.5.12", "")];
        let s = kea_conf(&cfg(), &res);
        assert_json_shape(&s);
        assert!(s.contains(r#"{ "hw-address": "aa:bb:cc:dd:ee:01", "ip-address": "192.168.5.11", "hostname": "node01" },"#));
        // no hostname -> no "hostname" key; the last reservation has no trailing comma
        assert!(s.contains(r#"{ "hw-address": "aa:bb:cc:dd:ee:02", "ip-address": "192.168.5.12" }"#));
        assert!(!s.contains(r#""192.168.5.12" },"#));

        // ONLY_KNOWN_HOSTS: no pool, so only the reserved hosts get an address
        let mut c = cfg();
        c.only_known_hosts = true;
        let s = kea_conf(&c, &res);
        assert_json_shape(&s);
        assert!(s.contains(r#""pools": [  ]"#) && !s.contains(r#""pool":"#));
    }

    #[test]
    fn kea_values_are_escaped() {
        let mut c = cfg();
        c.iface = "eth\"0".into();
        let s = kea_conf(&c, &[]);
        assert!(s.contains(r#""eth\"0""#));
        assert_json_shape(&s);
    }

    #[test]
    fn multicast_hooks_do_what_the_unicast_menu_does() {
        let c = cfg();
        let pre = prerun_hook(&c);
        let post = postrun_hook(&c);
        for h in [&pre, &post] {
            assert!(h.starts_with("#!/bin/sh\n"));
            assert!(!h.contains('@'), "unreplaced placeholder:\n{h}");
            // the MAC comes from the NIC that reaches the server, lower case, checked before it is used
            assert!(h.contains("ip -o route get 192.168.5.1"));
            assert!(h.contains("/sys/class/net/$dev/address"));
            assert!(h.contains("??:??:??:??:??:??"));
        }
        // start: same URL as the unicast ocs_prerun1; can never fail the restore
        assert!(pre.contains("http://192.168.5.1/cgi-bin/pxe-seed/$mac/start"));
        assert!(pre.contains("|| true") && pre.trim_end().ends_with("exit 0"));
        assert!(pre.contains("exit 0 ;;")); // no MAC: warn and carry on
        // post: same per-MAC post.sh as the unicast ocs_postrun1/2, once only, a failure is non-zero (no marker)
        assert!(post.contains("http://192.168.5.1/cgi-bin/pxe-seed/$mac/post.sh"));
        assert!(post.contains("sh /tmp/post.sh"));
        assert!(post.contains("/tmp/pxe-installer-post.done"));
        assert!(post.contains("exit 1 ;;"));
        // the one server-side script it fetches is rendered for a MAC and ends with the done callback
        let p = post_script(&c, "node01", "aa:bb:cc:dd:ee:01", "");
        assert!(p.contains("pxe-done?mac=aa:bb:cc:dd:ee:01") && p.contains("node01"));
    }

    #[test]
    fn tftpd_serves_the_tftp_root_read_only() {
        let s = tftpd_defaults(&cfg());
        assert!(s.contains("TFTP_DIRECTORY=\"/var/lib/tftpboot\""));
        assert!(s.contains("TFTP_OPTIONS=\"--secure\"")); // chroot, and no --create: read-only
        assert!(!s.contains("--create") && !s.contains("--permissive"));
    }

    #[test]
    fn grub_guard_and_clonezilla_entry() {
        let s = grub_cfg(&cfg());
        assert!(s.starts_with(GRUB_MARK));
        assert!(s.contains("/done/${net_default_mac}"));
        // kernel + initrd from the TFTP root, live filesystem over HTTP, image repository over NFS
        assert!(s.contains("linux /clonezilla/vmlinuz boot=live"));
        assert!(s.contains("initrd /clonezilla/initrd.img"));
        // no ip= argument at all: ip=dhcp and an empty ip= (-> frommedia) both break the network setup
        assert!(!s.contains(" ip="));
        assert!(s.contains("fetch=http://192.168.5.1/clonezilla/filesystem.squashfs"));
        assert!(s.contains(r#"ocs_prerun=\"mount -t nfs -o ro,vers=3,tcp,rsize=1048576 192.168.5.1:/home/partimag /home/partimag\""#));
        // the restore command targets the configured image and disk
        assert!(s.contains("restoredisk cri-golden nvme0n1"));
        assert!(s.contains("Restore cri-golden to /dev/nvme0n1 (ERASES THE DISK)"));
        // post-restore script is fetched per MAC; each command is its own ocs_postrunN
        assert!(s.contains("http://192.168.5.1/cgi-bin/pxe-seed/${net_default_mac}/post.sh"));
        assert!(s.contains(r#"ocs_postrun2=\"sh /tmp/post.sh\""#));
        // the restore entry (only) tells the server when the deploy starts: elapsed time = done - start
        assert_eq!(s.matches("/cgi-bin/pxe-seed/${net_default_mac}/start").count(), 1);
        assert!(s.contains(r#"ocs_postrun3=\"reboot\""#));
        // the restore entry is hands-free: no keyboard/language question, batch mode, no confirmation
        let restore = s.lines().find(|l| l.contains("restoredisk")).unwrap();
        for p in [r#"ocs_live_keymap=\"NONE\""#, r#"ocs_lang=\"en_US.UTF-8\""#, r#"ocs_live_batch=\"yes\""#, " -batch "] {
            assert!(restore.contains(p), "restore entry lacks {p}");
        }
        assert!(!restore.contains(" -c "), "a confirmation prompt would stop the unattended restore");
        // exactly one entry restores (and so erases) a disk
        assert_eq!(s.matches("restoredisk").count(), 1);
        // GRUB operators (&& ; | &) must not appear in the kernel lines
        for l in s.lines().filter(|l| l.trim_start().starts_with("linux ")) {
            assert!(!l.contains("&&") && !l.contains(';') && !l.contains('|'), "{l}");
        }
        // default entry: restore (1) with auto_install (the default), interactive (0) without
        assert!(s.contains("set default=1"));
        let mut c = cfg();
        c.auto_install = false;
        assert!(grub_cfg(&c).contains("set default=0"));
        // no unreplaced @PLACEHOLDER@
        assert!(!s.contains('@'));
    }

    #[test]
    fn grub_root_mode_tmpfs_or_nfs() {
        // default: the live system is downloaded into RAM
        let s = grub_cfg(&cfg());
        assert_eq!(s.matches("fetch=http://192.168.5.1/clonezilla/filesystem.squashfs").count(), 2);
        assert!(!s.contains("netboot=nfs") && !s.contains("nfsroot="));

        // NFS root: both entries mount the extracted Clonezilla Live folder, nothing is downloaded
        let mut c = cfg();
        c.root_mode = RootMode::Nfs;
        c.live_root = "/srv/nfs/clonezilla".into();
        let s = grub_cfg(&c);
        assert_eq!(s.matches("netboot=nfs nfsroot=192.168.5.1:/srv/nfs/clonezilla ").count(), 2);
        assert!(!s.contains("fetch="));
        // the image repository is still mounted, and the rest of the entries is unchanged
        assert!(s.contains("192.168.5.1:/home/partimag /home/partimag"));
        assert!(s.contains("restoredisk cri-golden nvme0n1"));
        assert!(!s.contains(" ip=") && !s.contains('@'));
    }

    #[test]
    fn grub_uses_configured_image_and_disk() {
        let mut c = cfg();
        c.image_name = "golden-2".into();
        c.target_disk = "sda".into();
        c.image_dir = "/srv/images".into();
        let s = grub_cfg(&c);
        assert!(s.contains("restoredisk golden-2 sda"));
        assert!(s.contains("192.168.5.1:/srv/images /home/partimag"));
    }

    #[test]
    fn post_script_identity_and_callback() {
        let s = post_script(&cfg(), "node07", "aa:bb:cc:dd:ee:01", "");
        assert!(s.starts_with("#!/bin/sh\n"));
        assert!(s.contains("echo \"node07\" > $T/etc/hostname"));
        assert!(s.contains("127.0.1.1 node07"));
        assert!(s.contains(": > $T/etc/machine-id"));
        assert!(s.contains("ssh_host_*"));
        assert!(s.contains("for p in /dev/nvme0n1?*; do"));
        assert!(s.contains("http://192.168.5.1/cgi-bin/pxe-done?mac=aa:bb:cc:dd:ee:01"));
        assert!(!s.contains('@'));
        // the callback is the last command: a failure before it leaves the host without a marker
        assert!(s.trim_end().lines().last().unwrap().contains("pxe-done"));
    }

    #[test]
    fn post_script_static_ip_from_the_binding() {
        // bound MAC: the address from `pxe-ctl bind`, with the subnet prefix (netplan needs a.b.c.d/nn)
        let s = post_script(&cfg(), "node07", "aa:bb:cc:dd:ee:01", "192.168.5.11");
        assert!(s.contains("ip_cidr=\"192.168.5.11/24\""));
        assert!(!s.contains('@'));
        // the three steps, in this order: backup folder, move the image's netplan files, write the new file
        let mkdir = s.find("mkdir -p $T/etc/netplan/backup").unwrap();
        let mv = s.find("mv \"$f\" $T/etc/netplan/backup/").unwrap();
        let new = s.find("cat > $T/etc/netplan/01-pxe-server-mac-binding.yaml").unwrap();
        assert!(mkdir < mv && mv < new);
        // only files are moved (the backup folder itself is in the glob), the PXE server's own file is just removed
        assert!(s.contains("if [ -f \"$f\" ]; then mv"));
        assert!(s.contains("rm -f $T/etc/netplan/60-pxe.yaml"));
        // the file content: eth0, the bound address, no DHCP; netplan wants it private
        assert!(s.contains("    eth0:\n      addresses:\n      - $ip_cidr\n      dhcp4: false\nEOF\n"));
        assert!(s.contains("chmod 600 $T/etc/netplan/01-pxe-server-mac-binding.yaml"));
        // all of it is before the FINAL unmount (the first `umount $T` is in the root-filesystem search loop) and
        // before the done callback
        let final_umount = s.rfind("umount $T\n").unwrap();
        assert!(new < final_umount);
        assert!(final_umount < s.find("pxe-done?mac=").unwrap());

        // unbound MAC: empty address, the script does nothing to the netplan files
        let u = post_script(&cfg(), "node07", "aa:bb:cc:dd:ee:01", "");
        assert!(u.contains("ip_cidr=\"\"\n"));

        // a different prefix is used for the address
        let mut c = cfg();
        c.prefix = 16;
        assert!(post_script(&c, "n", "aa:bb:cc:dd:ee:01", "192.168.5.11").contains("ip_cidr=\"192.168.5.11/16\""));
    }

    #[test]
    fn apache_network() {
        let a = apache_conf(&cfg());
        assert!(a.contains("Require ip 192.168.5.0/24"));
        assert!(a.contains("/cgi-bin/pxe-seed"));
    }
}
